using System;
using System.Linq;
using MET.Core;
// Focused economic fixtures deliberately seed warehouse stocks and ready freight
// nodes. These checks establish time, ownership, stock, freight and transaction
// invariants; they are not a no-injection development walkthrough or native UI proof.
class CityNetworkProgram {
 static int count;
 static void Assert(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static void Near(double a,double b,string label){Assert(Math.Abs(a-b)<1e-6*Math.Max(1,Math.Abs(b)),label+" ("+a+" / "+b+")");}
 static string Cell(Game g)=>Rules.ids(g.s["cells"]).First(x=>!g.s["cells"][x]["traits"].Contains("tile.water")&&g.s["cells"][x]["building"].Text=="").Text;
 static void Origin(CitySession w){var before=w.FocusedGame.snapshot();string error=w.FocusedGame.choose_origin(w.FocusedGame.s["origin_choices"][0].Text);if(error!="")throw new Exception(error);w.AfterLocalCommand(before);}
 static string Freight(Game g){var p=g.create_building("freight",Cell(g),"civic",true);g.refresh_metrics();p["usage"]=1;return p["id"].Text;}
 static CitySession World(Catalog c,int blocks=2){var w=new CitySession(c);w.BeginDistrict(0,"balanced");Origin(w);var first=w.FocusedBlockId;var g=w.FocusedGame;g.s["currency"]=3000;foreach(var r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=80;for(int i=1;i<blocks;i++){var e=w.BeginBlock(i%3,"balanced",first);if(e!="")throw new Exception(e);Origin(w);}w.ApplyWorldEffects();foreach(var game in w.Games.Values){var fid=Freight(game);game.s["projects"][fid]["inventory"]["material"]=130;}w.s["paused"]=false;foreach(var game in w.Games.Values){game.s["settings"]["user_paused"]=false;game.s["beta_time"]["pause_reason"]="";}return w;}
 static double Cargo(CitySession w,string resource)=>w.s["links"].Values.Where(x=>x["resource"].Text==resource).Sum(x=>x["buffer"].Double+x["inflight"].Sum(p=>p["amount"].Double));
 static double Stocks(CitySession w,string resource)=>w.Games.Values.Sum(g=>g.inventory_total(resource))+Cargo(w,resource);
 static void Settle(CitySession w,double seconds){w.SettleNetwork(seconds);w.s["external_seconds"]+=seconds;}
 static void Main(string[] args){var c=new Catalog(args[0]);
  var w=World(c,3);var ids=w.Games.Keys.ToArray();w.FocusBlock(ids[0]);string source=ids[0],a=ids[1],b=ids[2];
  Assert(w.CreateLink(source,a,"material",100,1)=="","create first real-stock link");Assert(w.CreateLink(source,b,"material",100,1)=="","create second competing link");double before=Stocks(w,"material");double cap=Market._total_capacity(w.Games[source]);
  Settle(w,3600);Near(Stocks(w,"material"),before,"dispatch conserves source+buffer+inflight");Near(w.s["network"]["last_tick"]["node_used"][source].Double,cap,"two links share one source freight capacity");Assert(Cargo(w,"material")>0,"dispatch creates saved in-flight cargo");double targetBefore=w.Games[a].inventory_total("material"),cash=w.Games.Values.Sum(g=>g.s["currency"].Double),treasury=w.s["treasury"].Double;
  Settle(w,3600);Near(Stocks(w,"material"),before,"arrival conserves all real network stock");Assert(w.Games[a].inventory_total("material")>targetBefore,"arrival reaches real target warehouse");Near(cash-w.Games.Values.Sum(g=>g.s["currency"].Double),w.s["treasury"].Double-treasury,"paid delivery transfers freight fee to city treasury");Assert(w.ValidateNetwork()=="","network shipment conservation validates");
  var serialized=w.snapshot();var restored=new CitySession(c);Assert(restored.Restore(serialized)=="","real in-flight/buffer envelope restores");Near(Stocks(restored,"material"),Stocks(w,"material"),"restore keeps all network stock");
  var m=World(c,2);foreach(var id in m.Games.Keys){var g=m.Games[id];Assert(Market.order(g,"goods","buy",200,100)=="","place outside order");g.s["currency"]=3000;}
  m.s["world_market"]["resources"]["goods"]["stock"]=1;m.s["world_market"]["resources"]["goods"]["replenishment_per_hour"]=0;double totalBefore=Stocks(m,"goods");Settle(m,3600);Near(Stocks(m,"goods")-totalBefore,1,"all Blocks share finite single outside stock");Near(m.s["world_market"]["resources"]["goods"]["stock"].Double,0,"outside stock withdraws once");
  var shared=World(c,2);var all=shared.Games.Keys.ToArray();shared.FocusBlock(all[0]);shared.CreateLink(all[0],all[1],"material",200,0);var sg=shared.Games[all[0]];Market.order(sg,"goods","buy",200,100);double usedCap=Market._total_capacity(sg);Settle(shared,3600);Near(shared.s["network"]["last_tick"]["node_used"][all[0]].Double,usedCap,"network and outside orders share endpoint capacity");Near(shared.s["network"]["last_tick"]["outside_trades"].Count,0,"capacity used by link is unavailable to outside trade");
  var normal=World(c,2);var fast=new CitySession(c);Assert(fast.Restore(normal.snapshot())=="","clone managed world for time comparison");string focus=normal.FocusedBlockId;normal.s["paused"]=false;fast.s["paused"]=false;foreach(var g in fast.Games.Values)g.s["settings"]["user_paused"]=false;double dt=fast.FocusedGame.s["dt"].Double;
  var nr=normal.Advance(30,"normal");var fr=fast.Advance(30,"advance");Assert(nr["reason"].Text==""&&fr["reason"].Text=="","normal and accelerated shared ticks commit");Near(normal.s["external_seconds"].Double,30,"normal uses External 1:1");Near(fast.s["external_seconds"].Double,30,"Local acceleration cannot accelerate shared world");Assert(fr["local_months"][focus].Double>nr["local_months"][focus].Double,"only authorized focus accelerates Local economy");foreach(var id in normal.Games.Keys)if(id!=focus)Near(fr["local_months"][id].Double,nr["local_months"][id].Double,"other Block stays External 1:1");foreach(var r in new[]{"food","material","goods"})Near(fast.s["world_market"]["resources"][r]["stock"].Double,normal.s["world_market"]["resources"][r]["stock"].Double,"Local speed does not mint outside "+r);Assert(fast.FocusedGame.s["dt"].Double<dt,"finite DT spent only by excess Local time");
  var beforeResume=fast.snapshot();fast.Resume(72000);Near(fast.s["external_seconds"].Double,beforeResume["external_seconds"].Double,"offline does not advance world");Near(fast.FocusedGame.s["dt"].Double,beforeResume["blocks"][focus]["state"]["dt"].Double,"offline does not refill finite DT");
  var atomic=World(c,2);var ag=atomic.Games[atomic.Games.Keys.First()];atomic.FocusBlock(ag==atomic.FocusedGame?atomic.FocusedBlockId:atomic.Games.Keys.First());atomic.CreateLink(atomic.Games.Keys.First(),atomic.Games.Keys.Last(),"material",20,0);Assert(atomic.Advance(30,"normal")["reason"].Text=="","prior valid shared slice commits");double retained=atomic.s["external_seconds"].Double;atomic.s["links"].Values[0]["dispatched"]+=99;var atomicBefore=atomic.snapshot().ToJson(sortKeys:true);var failed=atomic.Advance(30,"normal");Assert(failed["steps"].Long==0&&failed["reason"].Text!="","invalid conservation aborts entire candidate slice");Assert(atomic.snapshot().ToJson(sortKeys:true)==atomicBefore,"failed slice restores every Block plus world clock and inventory");Near(atomic.s["external_seconds"].Double,retained,"failed candidate retains earlier committed slices");
  var advanced=World(c,2);var advancedIds=advanced.Games.Keys.ToArray();advanced.FocusBlock(advancedIds[0]);advanced.Games[advancedIds[0]].s["projects"]["municipal"]["inventory"]["advanced_components"]=10;Assert(advanced.Advance(1,"normal")["reason"].Text=="","managed advanced stock baseline commits");Assert(advanced.CreateLink(advancedIds[0],advancedIds[1],"advanced_components",10,0)=="","advanced parts are independent network inventory");double advancedBefore=Stocks(advanced,"advanced_components");Settle(advanced,3600);Settle(advanced,3600);Settle(advanced,3600);Near(Stocks(advanced,"advanced_components"),advancedBefore,"advanced components conserve through in-flight and arrival");Near(advanced.Games[advancedIds[1]].inventory_total("advanced_components"),10,"advanced components reach actual target warehouse");foreach(var g in advanced.Games.Values)Near(g.s["audit"]["resources"]["advanced_components"]["error"].Double,0,"advanced network receipt closes resource audit");
  var autonomous=World(c,2);string oldDistrict=autonomous.ActiveDistrictId;autonomous.District(oldDistrict)["status"]="autonomous";autonomous.s["active_district_id"]="";autonomous.s["phase"]="choose_district";var oldGame=autonomous.FocusedGame;Bonus.draw(oldGame,"autonomy_fixture",V.Arr(),V.Map("kind","copy"));int queued=oldGame.s["block"]["reward_choices"].Count;double oldDt=oldGame.s["dt"].Double;autonomous.s["paused"]=false;var autoAdvance=autonomous.Advance(60,"advance");Assert(autoAdvance["reason"].Text==""&&autoAdvance["steps"].Long>0,"autonomous city continues during next District choice");Near(autoAdvance["local_seconds"].Double,60,"autonomous focus cannot use Local acceleration");Near(oldGame.s["dt"].Double,oldDt,"autonomous focus does not spend DT");Near(oldGame.s["block"]["reward_choices"].Count,queued,"autonomous economy preserves existing reward queue");Assert(!oldGame.s["settings"]["user_paused"].Bool,"autonomous saved decisions do not freeze economy");
  // Cross-District routing fixture: governance state is staged solely to exercise
  // transport delay/cost, while BeginDistrict still pays its actual startup sponsor.
  var cross=World(c,2);var crossSource=cross.Games.Keys.First();string crossOld=cross.ActiveDistrictId;cross.District(crossOld)["status"]="autonomous";cross.s["active_district_id"]="";cross.s["phase"]="choose_district";Assert(cross.BeginDistrict(2,"logistics")=="","cross District fixture pays actual old sponsor startup");Origin(cross);string crossTarget=cross.FocusedBlockId;Freight(cross.FocusedGame);cross.ApplyWorldEffects();Assert(cross.CreateLink(crossSource,crossTarget,"goods",5,1)=="","real link connects two different Districts");var crossLink=cross.s["links"].Values[0];double crossStock=Stocks(cross,"goods"),crossTargetStock=cross.FocusedGame.inventory_total("goods"),crossCash=cross.FocusedGame.s["currency"].Double;Settle(cross,3600);Assert(cross.SetLinkEnabled(crossLink["id"].Text,false)=="","disable stops new freight dispatch");Settle(cross,3600);Near(cross.FocusedGame.inventory_total("goods"),crossTargetStock,"inter District cargo retains actual longer travel delay");Settle(cross,3600);Near(Stocks(cross,"goods"),crossStock,"inter District delivery conserves actual stock");Near(cross.FocusedGame.inventory_total("goods")-crossTargetStock,5,"already dispatched freight arrives after link disabled");Near(crossCash-cross.FocusedGame.s["currency"].Double,10,"inter District delivered freight pays configured doubled cost");Near(crossLink["dispatched"].Double,5,"disabled edge does not withdraw another shipment");Assert(cross.Validate()=="","full cross District freight envelope validates");
  var effectsBefore=advanced.snapshot().ToJson(sortKeys:true);advanced.ApplyWorldEffects();advanced.ApplyWorldEffects();Assert(advanced.snapshot().ToJson(sortKeys:true)==effectsBefore,"world effect projection is idempotent and does not mint stock");
  var legacy=new Game(c);legacy.new_game(42,0);legacy.select_block(0);legacy.choose_origin(legacy.s["origin_choices"][0].Text);Assert(!legacy.world_managed,"legacy Game keeps autonomous Market ownership");var planner=new Planning();Assert(planner.copy_game(fast.FocusedGame).world_managed,"detached forecast preserves city ownership");
  var micro=World(c,2);var microIds=micro.Games.Keys.ToArray();micro.FocusBlock(microIds[0]);micro.CreateLink(microIds[0],microIds[1],"food",1,.15);var microLink=micro.s["links"].Values[0];double microStock=Stocks(micro,"food"),microTarget=micro.Games[microIds[1]].inventory_total("food");
  for(int i=0;i<1200;i++)Settle(micro,.5);
  Assert(microLink["inflight"].Count<=11,"1200 half-second dispatches retain only minute cargo buckets");Near(microLink["dispatched"].Double,600.0/3600,"micro dispatch retains exact actual shipped quantity");Near(Stocks(micro,"food"),microStock,"micro batches conserve source plus in-flight stock");Assert(micro.s["network"]["ledger"].Count<=11&&micro.s["world_market"]["ledger"].Count<=11,"micro settlement stores minute ledger entries");Near(micro.s["network"]["last_tick"]["external_seconds"].Double,.5,"last_tick remains an exact micro receipt");Near(micro.s["network"]["ledger"].Sum(x=>x["dispatches"].Sum(y=>y["amount"].Double)),microLink["dispatched"].Double,"minute ledger preserves summed dispatch amounts");
  foreach(var cargo in microLink["inflight"]) {double delay=cargo["arrival_external_seconds"].Double-cargo["departed_external_seconds"].Double-microLink["travel_seconds"].Double;Assert(delay>=0&&delay<=60,"fixed cargo bucket has no rolling delay beyond sixty seconds");Near(cargo["source_capacity"].Sum(x=>x["amount"].Double),cargo["amount"].Double,"merged cargo retains source allocation amount");}
  micro.SetLinkEnabled(microLink["id"].Text,false);Settle(micro,3059.5);Near(micro.Games[microIds[1]].inventory_total("food"),microTarget,"batched cargo cannot arrive before fixed sixty-second collection deadline");double microCash=micro.Games[microIds[1]].s["currency"].Double;Settle(micro,.5);double received=micro.Games[microIds[1]].inventory_total("food")-microTarget;Assert(received>0,"fixed first cargo batch arrives at recorded deadline");Near(microCash-micro.Games[microIds[1]].s["currency"].Double,received*.15,"micro batch delivery pays exact per-unit freight fee");Assert(micro.ValidateNetwork()=="","minute cargo invariant validates after arrival");
  var fills=World(c,1);var fg=fills.FocusedGame;fills.s["world_market"]["resources"]["goods"]["pricing"]["pressure"]=-1000;Assert(Market.order(fg,"goods","sell",100,-100)=="","managed microfill adverse export order accepted");if(fills.Advance(30,"normal")["reason"].Text!="")throw new Exception("pre-accept trade failed");Assert(Themes.select(fg,"logistics")=="","managed trade theme begins after earlier fills");fg.s["block"]["theme"]["events"].Add(V.Map("id","logistics_contract","status","offered","theme","logistics"));Assert(Themes.choose_event(fg,"logistics_contract","accept")=="","managed trade event captures actual acceptance boundary");var commission=V.Map("city_trade_baseline",fg.s["block"]["city_trade_totals"].Duplicate(true));Themes._update_events(fg,Themes._metrics(fg),.5);Near(Themes._find_event(fg,"logistics_contract")["progress"].Double,0,"event acceptance cannot replay previous exact receipt");
  var equivalent=new CitySession(c);Assert(equivalent.Restore(fills.snapshot())=="","equivalent batch clones accepted trade consumer state");
  for(int i=0;i<1200;i++) {var rr=fills.Advance(.5,"normal");if(rr["reason"].Text!="")throw new Exception("microfill advance: "+rr["reason"].Text);if(i==599){var loaded=new CitySession(c);if(loaded.Restore(fills.snapshot())!="")throw new Exception("microfill restore");fills=loaded;}}
  fg=fills.FocusedGame;var er=equivalent.Advance(600,"normal");Assert(er["reason"].Text=="","equivalent external batch commits");Near(fg.s["block"]["theme"]["counters"]["trade"].Double,4,"1200 compacted microfills all reach managed theme counter");Near(Themes._find_event(fg,"logistics_contract")["progress"].Double,4,"managed event counts each microfill once across save reload");Near(Commissions._metric(fg,"adverse_exports",commission),4,"long commission uses actual adverse-export totals beyond archived row cursors");Near(fg.s["block"]["theme"]["counters"]["trade"].Double,equivalent.FocusedGame.s["block"]["theme"]["counters"]["trade"].Double,"micro and equivalent batch preserve theme delivered amount");Near(Themes._find_event(fg,"logistics_contract")["progress"].Double,Themes._find_event(equivalent.FocusedGame,"logistics_contract")["progress"].Double,"micro and equivalent batch preserve event delivered amount");
  Assert(fg.s["block"]["trade_history"].Count<=12&&fg.s["block"]["trade_ledger"].Count<=12,"managed histories grow by minute rather than settlement count");double filled=fg.s["block"]["trade_orders"][0]["filled"].Double;Near(fg.s["block"]["trade_history"].Sum(x=>x["amount"].Double),filled,"compacted history amount equals actual order fills");Near(fg.s["block"]["trade_history"].Sum(x=>x["amount"].Double*x["price"].Double),fg.s["block"]["trade_orders"][0]["currency_delta_total"].Double,"compacted weighted price preserves exact settlement cash");var beforeConsumer=fg.snapshot().ToJson(sortKeys:true);Themes.tick(fg,.5);Assert(fg.snapshot().ToJson(sortKeys:true)==beforeConsumer,"same committed tick cannot replay managed trade consumers");Assert(fills.Validate()=="","saved managed aggregate counters validate");
  Console.WriteLine("CITY NETWORK CHECKS "+count+" passed");
 }
}
